# Actual funding stages remain distinct from unidentified reject outcomes.
if(!exists('selection_bias_sensitivity'))library(creditratingsystem)
st_source<-function(name){p<-file.path('creditratingsystem-r/examples',paste0(name,'.R'));if(!file.exists(p))p<-system.file('examples',paste0(name,'.R'),package='creditratingsystem');source(p)}
st_source('retail_application_journey')
st_date<-function(x,n)as.character(as.Date(x)+n)
st_audit<-function(product,records,target,model,calibrator,training_entities,cutoff,assumptions){
 target$performance_origin<-NULL;population<-paste0(product,'-through-door');mid<-model$model_id;pred<-rows<-apps<-decisions<-bookings<-outcomes<-list()
 for(r in records){key<-r$application_id;funded<-r$funded;observed<-r$observed;anchor<-if(funded)r$first_draw_at else r$application_at;end<-st_date(anchor,target$horizon)
 apps[[length(apps)+1L]]<-list(application_id=key,entity_id=r$customer_id,submitted_at=r$application_at)
 decisions[[length(decisions)+1L]]<-list(application_id=key,as_of=r$decision_at,known_at=r$decision_at,decision=if(r$offered)'offered'else'rejected',policy_version=r$policy_version)
 if(r$offered)bookings[[length(bookings)+1L]]<-list(application_id=key,as_of=if(funded)r$first_draw_at else r$decision_at,known_at=if(funded)r$first_draw_at else r$decision_at,taken_up=funded,funded=funded)
 if(funded)outcomes[[length(outcomes)+1L]]<-list(application_id=key,as_of=if(end<=cutoff)end else cutoff,known_at=cutoff,outcome_scope='own_contract',status=if(observed)'observed'else if(end>cutoff)'immature'else'censored',outcome=if(observed)r$outcome else NULL,target=target)
 rows[[length(rows)+1L]]<-list(prediction_id=key,application_id=key,entity_id=r$customer_id,cluster_id=r$customer_id,segment=product,as_of=anchor,forecast_known_at=r$application_at,horizon_end=end,known_at=cutoff,complete_through=if(observed&&r$outcome==0)end else NULL,model_id=mid,model_version='1',parameter_version='1',funded=funded,label_origin=if(observed)'OBSERVED_OWN_CONTRACT'else'UNOBSERVED',outcome=if(observed)r$outcome else NULL,target=target,weight=1)
 pred[[length(pred)+1L]]<-list(application_id=key,pd=r$pd,known_at=r$application_at)
 }
 panelargs<-list(applications=apps,decisions=decisions,bookings=bookings,outcomes=outcomes,as_of=cutoff,target_population=population,target=target);panel<-do.call(build_selection_dataset,panelargs)$value
 candidate<-list(model_id=mid,model_hash=content_fingerprint(list(model=model,calibrator=calibrator))$value,training_entities=training_entities,training_known_at=model$training$known_at,predictions=pred)
 flags<-vapply(records,function(r)as.integer(r$observed),0L);ys<-lapply(records,function(r)if(r$observed)r$outcome else NULL);weights<-rep(1,length(records));base<-list(observed=flags,target_weights=weights)
 configs<-list(list('MAR_FULL_SUPPORT','IPW',c(base,list(propensities=rep(assumptions$observation_propensity,length(records)))),selection_ipw_weights),list('MANSKI','BOUNDS',c(base,list(outcomes=ys)),reject_inference_bounds),list('MNAR_LOG_ODDS','MNAR_SHIFT',c(base,list(outcomes=ys,baseline_pd=vapply(records,function(r)r$pd,0.),log_odds_shifts=unlist(assumptions$log_odds_shifts))),reject_inference_sensitivity),list('NO_REJECT_SUPPORT','IPW',c(base,list(propensities=vapply(records,function(r)if(r$observed)assumptions$observation_propensity else 0,0.))),NULL))
 scenarios<-lapply(configs,function(z)list(result_id=z[[1]],kind=z[[2]],model_id=mid,population_id=population,target=target,application_ids=lapply(records,function(r)r$application_id),inputs=z[[3]],result=if(is.null(z[[4]]))NULL else do.call(z[[4]],z[[3]])$value))
 design<-list(model_id=mid,model_version='1',parameter_version='1',data_fingerprint=content_fingerprint(records)$value,population_id=population,split_id=paste0(product,'-independent-live-holdout'),prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,target=target)
 args<-list(candidates=list(candidate),evaluation_rows=rows,selection_results=scenarios,design=design,reference_model_id=mid);validated<-do.call(selection_bias_sensitivity,args)$value
 pseudoargs<-args;pseudoargs$selection_results<-list();pseudoargs$evaluation_rows<-lapply(rows,function(r){if(!r$funded){r$label_origin<-'PSEUDO';r$outcome<-1};r});pseudo<-do.call(selection_bias_sensitivity,pseudoargs)$value
 n<-length(records);m<-sum(unlist(flags));defaults<-sum(unlist(ys));bound<-scenarios[[2]]$result
 stopifnot(bound$lower==defaults/n,bound$upper==(defaults+n-m)/n,validated$metrics$mature_factual_count==m,pseudo$metrics$mature_factual_count==m,tail(validated$diagnostics$transport_scenarios,1)[[1]]$status=='NOT_IDENTIFIED_ZERO_SUPPORT',validated$decision$status=='NOT_ASSESSED')
 brier<-sum(vapply(records,function(r)if(r$observed)(r$pd-r$outcome)^2 else 0,0.))/m;stopifnot(abs(validated$metrics$evidence_scopes$FUNDED_OBSERVED_TEST[[mid]]$brier-brier)<1e-12)
 shift0<-Filter(function(x)x$log_odds_shift==0,scenarios[[3]]$result$surface)[[1]];oracle<-(defaults+sum(vapply(records,function(r)if(!r$observed)r$pd else 0,0.)))/n;stopifnot(abs(shift0$population_pd-oracle)<1e-12)
 summary<-list(application_ids=lapply(records,function(r)r$application_id),funded_facilities=lapply(Filter(function(r)r$funded,records),function(r)r$facility_id),target=target,index_convention='First actual draw for funded observations; application-date hypothetical funding for unbooked scenario rows. No unbooked performance is observed.',stage_counts=panel$counts,factual_count=m,funded_count=sum(vapply(records,function(r)r$funded,TRUE)),factual_defaults=defaults,brier=round(brier,8),bounds=bound,mar_effective_sample_size=scenarios[[1]]$result$effective_sample_size,mnar_population_pd=lapply(scenarios[[3]]$result$surface,function(x)list(log_odds_shift=x$log_odds_shift,population_pd=round(x$population_pd,8))),zero_support_status=tail(validated$diagnostics$transport_scenarios,1)[[1]]$status,pseudo_labels_change_factual_count=FALSE,selection_validation=validated$decision$status,assumptions=assumptions)
 list(summary=summary,records=records,panel_inputs=panelargs,panel=panel,validation_inputs=args,validation=validated,pseudo_control=pseudo,model=model,calibrator=calibrator)
}
st_application_records<-function(origin,case){Map(function(row,d){a<-row$application;l<-row$label;b<-Filter(function(x)x$application_id==a$application_id,case$bookings);observed<-isTRUE(l$mature)&&isTRUE(l$label_observed);list(application_id=a$application_id,customer_id=a$customer_id,facility_id=l$facility_id,application_at=a$application_at,decision_at=d$decided_at,first_draw_at=if(length(b))b[[1]]$first_draw_at else NULL,funded=l$funded,observed=observed,outcome=if(observed)l$target else NULL,offered=d$status=='approved',policy_version='1',pd=row$risk$pd)},origin$applications,case$decisions)}
st_card<-function(assumptions,case=NULL){
 st_source('revolving_lifecycle');p<-'RETAIL_CREDIT_CARD';source_data<-jsonlite::read_json(rj_resource('revolving_lifecycle.json'),simplifyVector=FALSE);if(!is.null(case))source_data$cases[[p]]<-case;case<-source_data$cases[[p]];ih<-'creditratingsystem-r/examples/input_lineage.R';if(!file.exists(ih))ih<-system.file('examples','input_lineage.R',package='creditratingsystem');journey<-run_revolving_lifecycle(source_data,product_ids=p,return_artifacts=TRUE,accounts_path=rj_resource('revolving_accounts.csv'),releases_path=rj_resource('revolving_releases.csv'),input_helper_path=ih)
 o<-journey$raw_artifacts$products[[p]]$origin;h<-.rl_history(case,p,o);replay<-journey$raw_artifacts$products[[p]]$replay;records<-Map(function(a,d,b,l,r){observed<-isTRUE(l$mature)&&isTRUE(l$label_observed);list(application_id=a$application_id,customer_id=a$customer_id,facility_id=b$facility_id,application_at=a$application_at,decision_at=d$decided_at,first_draw_at=b$first_draw_at,funded=TRUE,observed=observed,outcome=if(observed)l$target else NULL,offered=TRUE,policy_version='1',pd=r$pd)},case$applications,case$decisions,case$bookings,o$targets,o$risks);additional<-list()
 for(row in assumptions$unbooked_applications){pd<-predict_pd(o$model,matrix(row$recent_arrears,nrow=1),feature_order='recent_arrears',expected_target=case$application_target)$value;pd<-apply_calibrator(o$calibrator,pd,target=case$application_target,base_model_version=o$model$model_version)$value[[1]];if(!(row$evidence_observed_at<=row$evidence_known_at&&row$evidence_known_at<=row$application_at))stop('Affordability evidence must precede application');residual<-residual_income(row$monthly_net_income,row$monthly_expenses,row$existing_debt_service,row$proposed_minimum_payment,period='monthly',currency='EUR')$value;capacity<-if(residual$minimum>=0)'AFFORDABLE'else'NOT_AFFORDABLE';if(capacity!=row$affordability)stop('Documentary cash budget does not support declared affordability');dated<-list(as_of=row$application_at,known_at=row$application_at);inputs<-list(risk=c(list(pd=pd,target=case$application_target,freshness='CURRENT'),dated),affordability=c(list(status=row$affordability),dated),eligibility=c(list(status='ELIGIBLE'),dated),operations=c(list(status='CLEAR'),dated));decision<-do.call(apply_credit_decision_policy,c(list(policy=o$policy),inputs,dated))$value
 if(decision$action!=row$recorded_action)stop('Added card application decision does not reconcile')
 records[[length(records)+1L]]<-list(application_id=row$application_id,customer_id=row$customer_id,facility_id=NULL,application_at=row$application_at,decision_at=row$application_at,first_draw_at=NULL,funded=FALSE,observed=FALSE,outcome=NULL,offered=decision$action=='APPROVE',policy_version='1',pd=pd);additional[[length(additional)+1L]]<-list(source=row,decision_inputs=inputs,decision=decision,conditional_transport_pd=pd,residual_income=residual)
 }
 policy_validation<-st_card_policy(case,o,additional,records,'2025-01-02')
 result<-st_audit(p,records,case$application_target,o$model,o$calibrator,list(),'2025-01-02',assumptions);result$summary<-c(result$summary,list(cohort_status=h$cohort$decision$status,replay_status=replay$validation$decision$status,policy_stage_actions=c(lapply(o$decisions,function(r)r$action),lapply(additional,function(r)r$decision$action)),economic_policy_outcomes='UNKNOWN_365_DAY_NET_PROFIT; actual approval, uptake and funded amounts validated',policy_factual=policy_validation$result$metrics$factual,policy_violations=policy_validation$result$violation_counts,policy_validation_status=policy_validation$result$decision$status,transport_population='Original funded-only model unchanged; two unbooked PDs are explicitly assumed conditional transfers',source_funded_population=o$model$application_contract$population_ids,source_lineage_status=journey$source_lineage_status,governance_replayed=journey$products[[p]]$governance_replayed));c(result,list(policy_validation=policy_validation,origin=o,history=h,replay=replay,source_case=case,funded_journey=journey,additional_applications=additional,prediction_design=c(lapply(o$snapshots,function(s)list(s$features$recent_arrears)),lapply(additional,function(r)list(r$source$recent_arrears)))))
}
run_selection_transport<-function(data=NULL,product_ids=NULL,return_artifacts=FALSE){
 if(is.null(data))data<-jsonlite::read_json(rj_resource('selection_transport.json'),simplifyVector=FALSE);chosen<-if(is.null(product_ids))names(data$products)else unlist(product_ids);out<-chains<-list();base<-jsonlite::read_json(rj_resource('retail_application_journey.json'),simplifyVector=FALSE);regular<-intersect(chosen,names(base$products))
 if(length(regular)){chain<-run_retail_application_journey(product_ids=regular,return_artifacts=TRUE);for(p in regular)chains[[p]]<-list(origin=chain$products[[p]],case=base$products[[p]],target=base$target,cutoff=base$evaluation_cutoff)}
 if('RETAIL_SMALL_BUSINESS_FINANCE'%in%chosen){st_source('retail_owner_journey');owned<-run_retail_owner_journey(return_artifacts=TRUE,include_lifecycle=FALSE);ownerdata<-jsonlite::read_json(rj_resource('retail_owner_journey.json'),simplifyVector=FALSE);p<-'RETAIL_SMALL_BUSINESS_FINANCE';chains[[p]]<-list(origin=owned$application_chain$products[[p]],case=ownerdata$products[[p]],target=ownerdata$target,cutoff=ownerdata$evaluation_cutoff)}
 for(p in names(chains)){z<-chains[[p]];o<-z$origin;f<-o$fitted;out[[p]]<-st_audit(p,st_application_records(o,z$case),z$target,f$model,f$calibrator,lapply(c(f$training_rows,f$calibration_rows),function(r)r$customer_id),z$cutoff,data$products[[p]]);out[[p]]$source_origin<-o;out[[p]]$source_case<-z$case;out[[p]]$prediction_design<-lapply(o$applications,function(r)list(r$snapshot$features$driver));out[[p]]$summary<-c(out[[p]]$summary,list(cohort_status=o$performing$validation$decision$status,policy_factual=o$policy_validation$result$metrics$factual,policy_violations=o$policy_validation$result$violation_counts,replay_status=o$monitoring$replay_validation$decision$status))}
 if('RETAIL_CREDIT_CARD'%in%chosen)out[['RETAIL_CREDIT_CARD']]<-st_card(data$products[['RETAIL_CREDIT_CARD']])
 result<-list(journey_id='J_SELECTION_TRANSPORT',data_origin='SYNTHETIC',products=lapply(out,function(x)x$summary),interpretation='Observed own-contract holdout and hypothetical transport are separate. MAR propensity and MNAR shifts are assumptions, not estimated selection effects. No full-population validation or causal policy approval is claimed.');if(return_artifacts)result$raw_artifacts<-out;result
}
st_card_policy<-function(case,origin,additional,records,cutoff){
 target<-case$application_target;product<-'RETAIL_CREDIT_CARD';candidate<-list(candidate_id='historical',policy=origin$policy,offer_rule_reference='Recorded initial card authorization terms; no identified uptake or profitability model');cases<-inputs<-outcomes<-historical<-list()
 for(i in seq_along(records)){r<-records[[i]];key<-r$application_id;D<-r$decision_at;dated<-list(as_of=D,known_at=D);funded<-r$funded
 if(i<=length(case$applications)){di<-list(risk=c(origin$risks[[i]],list(freshness='CURRENT'),dated),affordability=c(list(status=origin$capacities[[i]]$assessment$assessment),dated),eligibility=c(list(status='ELIGIBLE'),dated),operations=c(list(status='CLEAR'),dated));decision<-origin$decisions[[i]];amount<-case$applications[[i]]$requested_terms$amount}else{a<-additional[[i-length(case$applications)]];di<-a$decision_inputs;decision<-a$decision;amount<-a$source$requested_limit}
 offer<-list(offer_id=key,version='1',known_at=D,currency='EUR',target=target,risk_conditioning='CONDITIONAL_ON_THIS_ACCEPTED_OFFER',assumption_reference='Original initial authorization terms. No take-up probability or complete365day profitability model identified.',support_status='UNSUPPORTED',takeup_probability=NULL,conditional_booked_expected_loss=NULL,conditional_booked_npv=NULL,ead=NULL,offer_cost=NULL,contract_terms=list(limit=amount,tenor_days=365,currency='EUR',interest_rate_status='NOT_SUPPLIED'))
 cases[[i]]<-list(case_id=key,decision_date=D,weight=1,split_id='card-through-door-heldout',prediction_reference='Original frozen funded-only model; unbooked predictions explicitly assumption-conditional',excluded_from_model_training=TRUE,excluded_from_calibration=TRUE);inputs[[i]]<-c(list(candidate_id='historical',case_id=key),di,list(offer=offer,nonapproval_costs=list(REFER=0,DECLINE=0,BLOCKED=0)))
 matches<-Filter(function(b)b$application_id==key,case$bookings);b<-if(length(matches))matches[[1]]else NULL;end<-if(funded)st_date(b$first_draw_at,365)else NULL
 outcomes[[i]]<-list(case_id=key,funded=funded,complete=FALSE,booked_offer_hash=if(funded)content_fingerprint(offer)$value else NULL,funded_at=if(funded)b$first_draw_at else NULL,funding_known_at=if(funded)b$first_draw_known_at else NULL,outcome_end=end,known_at=NULL,defaulted=NULL,economic_loss=NULL,net_profit=NULL)
 initial_draw<-if(funded)sum(vapply(Filter(function(t)t$account_id==b$facility_id&&t$date==b$first_draw_at&&t$kind=='DRAW',case$transactions),function(t)t$amount,0.))else NULL
 historical[[i]]<-list(prediction_id=key,case_id=key,entity_id=r$customer_id,cluster_id=r$customer_id,segment=product,as_of=D,forecast_known_at=D,horizon_end=st_date(D,365),model_id='card-policy-audit',model_version='1',parameter_version='1',weight=1,historical_candidate_id='historical',historical_decision=decision,offered=r$offered,taken_up=funded,offered_limit=if(r$offered)amount else NULL,booked_amount=initial_draw,stages_known_at=if(funded)b$first_draw_known_at else D,application_cost=NULL,cost_known_at=NULL,cost_complete=FALSE)
 }
 profile<-list(profile_id='card-policy-evidence',version='1',target_contract_version='1.1',known_at='2023-12-31',registered_at='2023-12-31',outcome_access_date=cutoff,currency='EUR',evaluation_role='TEST',prediction_design='HELD_OUT',split_id='card-through-door-heldout',data_fingerprint=content_fingerprint(records)$value,target=target,candidate_hashes=list(historical=content_fingerprint(candidate)$value),objective='expected_npv_per_application',constraints=list(),tie_break='candidate_id',tolerance=1e-12,loss_bounds=c(0,2000),profit_bounds=c(-2000,2000))
 gridargs<-list(policy_candidates=list(candidate),cases=cases,candidate_inputs=inputs,observed_outcomes=outcomes,evaluation_profile=profile,evaluation_cutoff=cutoff);grid<-do.call(evaluate_decision_grid,gridargs)$value;design_target<-target;design_target$performance_origin<-NULL
 design<-list(model_id='card-policy-audit',model_version='1',parameter_version='1',data_fingerprint=profile$data_fingerprint,population_id=paste0(product,'-through-door'),split_id=profile$split_id,prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,currency='EUR',target=design_target,policy_target_contract_version='1.1',performance_origin='first_draw_at')
 args<-list(evaluated_grid=grid,grid_inputs=gridargs,historical_cases=historical,design=design,reference_candidate_id='historical');validated<-do.call(decision_policy_backtest,args)$value;stopifnot(length(validated$violation_counts)==0,validated$metrics$factual$funded_rate==.6,validated$metrics$factual$offered_rate==.8,is.null(validated$metrics$factual$observed_pd));list(inputs=args,result=validated)
}
